const fs = require('fs');
const path = require('path');
const body = $input.first().json.body || $input.first().json;
const node = (body.node || 't440').toLowerCase();
const action = body.action || '';
if (!action) throw new Error('action required');
const repo = body.repo || '/data/codebase/repos/wreckhunter2000-1';
let health = {};
try {
  const hp = path.join(repo, 'var/fleet-health/latest.json');
  if (fs.existsSync(hp)) health = JSON.parse(fs.readFileSync(hp, 'utf8'));
} catch (e) {}
const n8nBase = health.n8n_url || health.n8n_bridge || 'http://127.0.0.1:5678';
const mcpBase = (health.mcp_worker || 'http://127.0.0.1:8090').replace(/\/$/, '');
const ts = new Date().toISOString().replace(/[:.]/g, '-');
const jobId = `job_${ts}_${Math.random().toString(36).slice(2, 8)}`;
const jobObj = { ...body, node, action, job_id: jobId, requested_at: new Date().toISOString(), health_endpoints: health.endpoints || {} };
const job = JSON.stringify(jobObj);
const queuePath = `${repo}/var/fleet-jobs/pending/${node}/${jobId}.json`;
const mcpUrl = body.mcp_url || `${mcpBase}/tool/run_command`;
let localCmd = '';
if (node === 't440') {
  localCmd = `bash ${repo}/scripts/fleet-job-runner.sh`;
} else {
  localCmd = `FLEET_DISPATCH=nfs bash ${repo}/scripts/fleet-n8n-dispatch.sh ${node} ${action}`;
}
return [{ json: { node, action, jobId, queuePath, job, mcpUrl, n8nBase, localCmd, repo, health } }];

const j = $('Parse Fleet Job').first().json;
const out = $input.first().json;
return [{ json: {
  ok: true,
  node: j.node,
  action: j.action,
  job_id: j.jobId,
  queue: j.queuePath,
  dispatch: j.node === 't440' ? 'executeCommand' : 'nfs_enqueue+mcp_optional',
  stdout: out.stdout || out.result || JSON.stringify(out).slice(0, 2000)
} }];
